// Pseudo-code: streaming inference skeleton
async function process(batch){
  const lang = detectLanguage(batch)
  const tokens = tokenize(batch, lang)
  const entities = nerModel.predict(tokens, lang)
  const relations = relModel.predict(entities)
  return formatEvent(entities, relations)
}
```

